witness_check.proof_type:
have q := ∏ m ∈ B, ↑m;
have S := ∑ m ∈ B, 1 / ↑↑m;
(↑q)⁻¹ * ∑ j ∈ Finset.range q, (1 - (∑ m ∈ B, if ↑m ∣ j + 1 then 1 else 0) / S) ^ 2 =
  S⁻¹ ^ 2 * ∑ m ∈ B, ∑ n ∈ B, ↑((↑n).gcd ↑m) / (↑↑n * ↑↑m) - 1

