witness_check.proof_type:
have A := fun M c => (↑M)⁻¹ * ∑ k ∈ Finset.range M, c ⟨k + 1, ⋯⟩;
have S := ∑ m ∈ B, 1 / ↑↑m;
have Sℂ := ∑ m ∈ B, 1 / ↑↑m;
have actual := ∑ m ∈ B, (A (N / ↑m) fun k => a ⟨↑m * ↑k, ⋯⟩) / ↑↑m;
have ideal := ∑ m ∈ B, (↑N)⁻¹ * ∑ k ∈ Finset.range (N / ↑m), a ⟨↑m * (k + 1), ⋯⟩;
‖A N a - actual / Sℂ - (A N a - ideal / Sℂ)‖ ≤ ↑B.card / (↑N * S)

